import("stdfaust.lib");
freq = hslider("freq",440,20,8000,0.01);
gain = hslider("gain",0.5,0,1,0.01);
gate = button("gate");
attack = hslider("Attack[unit:s]",0.5,0.01,5,0.01);
decay = hslider("Decay[unit:s]",0.5,0.01,5,0.01);
sustain = hslider("Sustain",0.8,0,1,0.01);
release = hslider("Release[unit:s]",1.0,0.01,10,0.01);
env = en.adsr(attack,decay,sustain,release,gate);
detune = hslider("Detune[unit:Hz]",5,0,50,0.01):si.smoo;
unisonMix = hslider("UnisonMix",0.5,0,1,0.01):si.smoo;
cutoff = hslider("Cutoff[unit:Hz]",2000,50,8000,1):si.smoo;
resonance = hslider("Resonance",0.7,0.1,5,0.01):si.smoo;
mainOsc = os.sawtooth(freq);
unisonOsc = (os.sawtooth(freq+detune)+os.sawtooth(freq-detune))*unisonMix;
voice = mainOsc+unisonOsc;
process = voice:fi.resonlp(cutoff,resonance,1):*(gain*env);

import("stdfaust.lib");
freq = hslider("freq", 440, 20, 8000, 0.01);
gain = hslider("gain", 0.5, 0, 1, 0.01);
gate = button("gate");
ratio = hslider("Ratio", 2.0, 0.5, 8.0, 0.01) : si.smoo;
modIndex = hslider("ModIndex", 5.0, 0, 20, 0.01) : si.smoo;
subMix = hslider("SubMix", 0.5, 0, 1, 0.01) : si.smoo;
attack = hslider("Attack[unit:s]", 0.01, 0.001, 2, 0.001) : si.smoo;
decay = hslider("Decay[unit:s]", 1.0, 0.001, 5, 0.001) : si.smoo;
sustain = hslider("Sustain", 0, 0, 1, 0.01) : si.smoo;
release = hslider("Release[unit:s]", 0.2, 0.001, 5, 0.001) : si.smoo;
env = en.adsr(attack, decay, sustain, release, gate);
