import("stdfaust.lib");
freq = hslider("freq", 440, 20, 8000, 0.01);
gain = hslider("gain", 0.5, 0, 1, 0.01);
gate = button("gate");
pluckMix = hslider("PluckMix", 1, 0, 1, 0.01) : si.smoo;
pluckAttack = hslider("PluckAttack[unit:s]", 0.001, 0.001, 0.1, 0.001);
pluckDecay = hslider("PluckDecay[unit:s]", 0.2, 0.01, 5, 0.001);
stringCutoff = hslider("StringCutoff[unit:Hz]", 2000, 200, 8000, 1) : si.smoo;
stringRes = hslider("StringResonance", 0.7, 0, 1, 0.01) : si.smoo;
noiseMix = hslider("NoiseMix", 0.5, 0, 1, 0.01) : si.smoo;
noiseAttack = hslider("NoiseAttack[unit:s]", 0.01, 0.001, 1, 0.001);
noiseDecay = hslider("NoiseDecay[unit:s]", 0.1, 0.001, 2, 0.001);
noiseSustain = hslider("NoiseSustain", 0.8, 0, 1, 0.01);
noiseRelease = hslider("NoiseRelease[unit:s]", 0.5, 0.001, 5, 0.001);
noiseCutoff = hslider("NoiseCutoff[unit:Hz]", 1500, 100, 5000, 1) : si.smoo;
noiseRes = hslider("NoiseResonance", 0.5, 0, 1, 0.01) : si.smoo;
pluckEnv = en.ar(pluckAttack, pluckDecay, gate);
stringOsc = os.sawtooth(freq);
stringFiltered = stringOsc : fi.resonlp(stringCutoff, stringRes, 1);
string = (stringFiltered * pluckEnv) * pluckMix;
noiseEnv = en.adsr(noiseAttack, noiseDecay, noiseSustain, noiseRelease, gate);
noise = no.noise : fi.resonlp(noiseCutoff, noiseRes, 1);
noiseLayer = (noise * noiseEnv) * noiseMix;
process = (string + noiseLayer) * gain;

